values
  ('ALLOCATION_DRIFT_IMPACT', 'Allocation Drift Impact', ARRAY['investment_growth']::text[], 'Deterministic calculation used by investment_growth recommendations. It must use the saved forecast inputs and selected scenario, and must not generate unsupported values.', 'InvestmentForecastService', ARRAY['current_allocation', 'forecast_status', 'future_contributions', 'revised_forecast_value', 'target_allocation', 'transaction_costs', 'variance_amount', 'variance_percentage', 'variance_result']::text[], ARRAY['alternative_asset_mix', 'estimated_future_impact', 'largest_allocation_drift', 'recommended_reallocation_amount', 'revised_forecast_value', 'variance_amount', 'variance_percentage']::text[], 'Currency: 2 decimals; percentages: 2 decimals; dates: whole day; months: whole month', ARRAY['base', 'conservative', 'optimistic', 'custom']::text[], true, 1, 'Calculation code and recommendation wording must remain separately maintainable.'),
  ('COMPLETED_GOAL_REDIRECTION_IMPACT', 'Completed Goal Redirection Impact', ARRAY['goal']::text[], 'Deterministic calculation used by goal recommendations. It must use the saved forecast inputs and selected scenario, and must not generate unsupported values.', 'GoalForecastService', ARRAY['forecast_status', 'goal_target', 'goal_value', 'monthly_contribution', 'next_priority', 'revised_forecast_value', 'variance_amount', 'variance_percentage', 'variance_result']::text[], ARRAY['estimated_future_impact', 'goal_surplus', 'next_goal_name', 'released_monthly_contribution', 'revised_forecast_value', 'variance_amount', 'variance_percentage']::text[], 'Currency: 2 decimals; percentages: 2 decimals; dates: whole day; months: whole month', ARRAY['base', 'conservative', 'optimistic', 'custom']::text[], true, 1, 'Calculation code and recommendation wording must remain separately maintainable.'),
